module.exports = {"FORGE_BODY_GUIDANCE":"When posting a PR/MR description or comment, never pass `@-` or `-` as the body value: `glab mr create --description`, `glab mr update --description`, `glab mr note -m` and `gh pr create --body` post the string you hand them verbatim, so `@-` reaches the forge as the literal two characters and the body you meant to send is lost. Write multi-line bodies to a file and pass them with a mechanism the command actually supports: `--body-file body.md` for gh, `--description \"$(cat body.md)\"` or `-m \"$(cat body.md)\"` for glab, or `glab api ... -F 'description=@body.md'`.","STDIN_MARKERS":["@-","-"]};
